    private int quantity;

    public Stock(String name, int quantity) {
        this.name = name;
        this.quantity = quantity;
    }

    public String getName() { return name; }

    public int getQuantity() { return quantity; }

    public void restock(int amount) { quantity += amount; }

    public boolean sell(int amount) {
        if (amount <= quantity) {
            quantity -= amount;
            return true;
        }
        return false;
    }
}

public class Scoreboard {
    private int target;
    private int home;
    private int away;

    public Scoreboard(int target) {
        this.target = target;
        home = 0;
        away = 0;
    }

    public void scoreHome(int points) { home += points; }

    public void scoreAway(int points) { away += points; }

    public String leader() {
        if (home > away) return "home";
        if (away > home) return "away";
        return "tie";
    }

    public boolean isOver() {
        return home >= target || away >= target;
    }
}

public class LimitedCounter {
    private int limit;
    private int count;

    public LimitedCounter(int limit) {
        this.limit = limit;
        count = 0;
    }

    public boolean increment() {
        if (count < limit) {
            count++;
            return true;
        }
        return false;
    }

    public void reset() {
        count = 0;
    }

    public int remaining() {
        return limit - count;
    }
}

